//
// Perform enrichment analysis
//
include { GPROFILER2_GOST          } from 'nf-core/gprofiler2/gost'
include { CUSTOM_TABULARTOGSEAGCT  } from 'nf-core/custom/tabulartogseagct'
include { CUSTOM_TABULARTOGSEACLS  } from 'nf-core/custom/tabulartogseacls'
include { CUSTOM_TABULARTOGSEACHIP } from 'nf-core/custom/tabulartogseachip'
include { GSEA_GSEA                } from 'nf-core/gsea/gsea'
include { PROPR_GREA               } from 'nf-core/propr/grea'
include { DECOUPLER_DECOUPLER      } from 'nf-core/decoupler/decoupler'

// Combine meta maps, including merging non-identical values of shared keys (e.g. 'id')
def mergeMaps(meta, meta2){
    (meta + meta2).collectEntries { k, v ->
        meta[k] && meta[k] != v ? [k, "${meta[k]}_${v}"] : [k, v]
    }
}

workflow DIFFERENTIAL_FUNCTIONAL_ENRICHMENT {
    take:
    // input data for functional analysis
    // Note that genesets and background are optional depending on the method.
    // Please set to [] if not provided, eg: [meta, input, [], [], method]
    ch_input                 // [ meta, input file, genesets file, background file, method to run ]

    // other - for the moment these files are only needed for GSEA
    // as it is the only one that takes expression data as input
    // if in the future this setting is changed, this section could be removed
    ch_contrasts             // [ meta, [meta_contrast], [variable], [reference], [target], [formula], [comparison] ]
    ch_samplesheet           // [ meta, samples sheet ]
    ch_featuresheet          // [ meta, features sheet, features id, features symbol ]

    main:
    // Add method information into meta map of ch_input
    // This information is used later to determine which method to run for each input
    // Also, reorganize the structure to match them with the modules' input organization
    ch_input_for_other = ch_input
        .join(ch_featuresheet)
        .multiMap { meta, file, genesets, background, method, features_sheet, features_id, features_symbol ->
            def meta_with_method = meta + [ 'functional_method': method ]
            input:
                [ meta_with_method, file ]
            genesets:
                [ meta_with_method, genesets ]
            background:
                [ meta_with_method, background ]
            features:
                [ meta_with_method, features_sheet, features_id, features_symbol]
        }

    // In the case of GSEA, it needs additional files coming from other channels that other methods don't use
    // here we define the input channel for the GSEA section

    def criteria = multiMapCriteria { meta, input, genesets, _background, method, samplesheet, featuresheet, features_id, features_symbol, meta_contrast, _variable, _reference, _target, _formula, _comparison ->
        def meta_with_method = meta + [ 'functional_method': method ]
        def meta_with_contrast = mergeMaps(meta_contrast, meta_with_method)
        input:
            [ meta_with_contrast, input ]
        genesets:
            [ meta_with_contrast, genesets ]
        contrasts_and_samples:
            [ meta_with_contrast, samplesheet ]
        features:
            [ meta_with_contrast, featuresheet ]
        features_cols:
            [ features_id, features_symbol ]
    }

    // GSEA uses meta.variable, so only keep contrasts where meta.variable is present
    ch_contrasts_transposed = ch_contrasts.transpose()
        .filter { _meta, _contrastMap, variable, _reference, _target, _formula, _comparison ->
            variable?.trim()
        }

    ch_input_for_gsea = ch_input
        .filter{ it -> it[4] == 'gsea' }
        .combine(ch_samplesheet.join(ch_featuresheet), by:0)
        .combine(ch_contrasts_transposed, by:0)
        .multiMap(criteria)


    // ----------------------------------------------------
    // Perform enrichment analysis with gprofiler2
    // ----------------------------------------------------

    GPROFILER2_GOST(
        ch_input_for_other.input.filter{ index -> index[0].functional_method == 'gprofiler2' },
        ch_input_for_other.genesets.filter{ index -> index[0].functional_method == 'gprofiler2'},
        ch_input_for_other.background.filter{ index -> index[0].functional_method == 'gprofiler2'}
    )

    // ----------------------------------------------------
    // Perform enrichment analysis with GSEA
    // ----------------------------------------------------

    CUSTOM_TABULARTOGSEAGCT(ch_input_for_gsea.input)
    CUSTOM_TABULARTOGSEACLS(ch_input_for_gsea.contrasts_and_samples)
    CUSTOM_TABULARTOGSEACHIP(
        ch_input_for_gsea.features,
        ch_input_for_gsea.features_cols
    )

    ch_in_gsea = CUSTOM_TABULARTOGSEAGCT.out.gct
        .join(CUSTOM_TABULARTOGSEACLS.out.cls)
        .join( ch_input_for_gsea.genesets )
        .join( CUSTOM_TABULARTOGSEACHIP.out.chip )
        .multiMap { meta, gct, cls, genesets, chip ->
            input:
            [meta, gct, cls, genesets]
            ref_target:
            [meta.reference, meta.target]
            chip:
            [meta, chip]
        }

    GSEA_GSEA(
        ch_in_gsea.input,
        ch_in_gsea.ref_target,
        ch_in_gsea.chip
    )

    // ----------------------------------------------------
    // Perform enrichment analysis with DECOUPLER
    // ----------------------------------------------------

    DECOUPLER_DECOUPLER(
        ch_input_for_other.input.filter{ index -> index[0].functional_method == 'decoupler' },
        ch_input_for_other.genesets.filter{ index -> index[0].functional_method == 'decoupler'},
        ch_input_for_other.features.filter{ index -> index[0].functional_method == 'decoupler'}
            .map{ meta, features_sheet, _features_id, _features_symbol -> [meta, features_sheet] }
    )

    // ----------------------------------------------------
    // Perform enrichment analysis with GREA
    // ----------------------------------------------------

    PROPR_GREA(
        ch_input_for_other.input.filter{ index -> index[0].functional_method == 'grea' },
        ch_input_for_other.genesets.filter{ index -> index[0].functional_method == 'grea' }
    )

    // ----------------------------------------------------
    // collect generic outputs
    // ----------------------------------------------------

    ch_session_info = GPROFILER2_GOST.out.session_info

    emit:
    // here we emit the outputs that will be useful afterwards in the
    // nf-core/differentialabundance pipeline

    // gprofiler2-specific outputs
    gprofiler2_plot_html            = GPROFILER2_GOST.out.plot_html
    gprofiler2_all_enrich           = GPROFILER2_GOST.out.all_enrich
    gprofiler2_sub_enrich           = GPROFILER2_GOST.out.sub_enrich
    gprofiler2_artifacts            = GPROFILER2_GOST.out.plot_png
    gprofiler2_sub_plot             = GPROFILER2_GOST.out.sub_plot
    gprofiler2_rds                  = GPROFILER2_GOST.out.rds
    gprofiler2_filtered_gmt         = GPROFILER2_GOST.out.filtered_gmt

    // gsea-specific outputs
    gsea_report_tsv                 = GSEA_GSEA.out.report_tsvs_ref.join(GSEA_GSEA.out.report_tsvs_target)
    gsea_report_html                = GSEA_GSEA.out.report_htmls_ref.join(GSEA_GSEA.out.report_htmls_target)
    gsea_index_html                 = GSEA_GSEA.out.index_html
    gsea_heat_map_corr_plot         = GSEA_GSEA.out.heat_map_corr_plot
    gsea_ranked_gene_list           = GSEA_GSEA.out.ranked_gene_list
    gsea_gene_set_sizes             = GSEA_GSEA.out.gene_set_sizes
    gsea_histogram                  = GSEA_GSEA.out.histogram
    gsea_heatmap                    = GSEA_GSEA.out.heatmap
    gsea_pvalues_vs_nes_plot        = GSEA_GSEA.out.pvalues_vs_nes_plot
    gsea_ranked_list_corr           = GSEA_GSEA.out.ranked_list_corr
    gsea_butterfly_plot             = GSEA_GSEA.out.butterfly_plot
    gsea_gene_set_tsv               = GSEA_GSEA.out.gene_set_tsv
    gsea_gene_set_html              = GSEA_GSEA.out.gene_set_html
    gsea_gene_set_heatmap           = GSEA_GSEA.out.gene_set_heatmap
    gsea_gene_set_enplot            = GSEA_GSEA.out.gene_set_enplot
    gsea_gene_set_dist              = GSEA_GSEA.out.gene_set_dist
    gsea_snapshot                   = GSEA_GSEA.out.snapshot
    gsea_archive                    = GSEA_GSEA.out.archive
    gsea_rpt                        = GSEA_GSEA.out.rpt

    // decoupler-specific outputs
    decoupler_dc_estimate           = DECOUPLER_DECOUPLER.out.dc_estimate
    decoupler_dc_pvals              = DECOUPLER_DECOUPLER.out.dc_pvals
    decoupler_png                   = DECOUPLER_DECOUPLER.out.png

    // grea-specific outputs
    grea_results                    = PROPR_GREA.out.results

    // tool versions
    session_info                    = ch_session_info
}

process {

    cpus = 1

    withName: 'DESEQ2_DIFFERENTIAL' {
        ext.args = { [
            "--round_digits 5",
            "--vs_method rlog",
            (meta.blocking == null) ? "" : "--blocking_variables $meta.blocking"
        ].join(' ').trim() }
        ext.prefix = { "${meta.id}_${meta.method_differential}" }
    }

    withName: 'DESEQ2_NORM' {
        ext.prefix = { "${meta.id}_${meta.method_differential}_norm" }
    }

    withName: 'LIMMA_DIFFERENTIAL' {
        ext.args = { [
            "--blocking_variables $meta.blocking",
            "--sample_id_col sample",
            "--probe_id_col gene_id",
            "--use_voom TRUE"
        ].join(' ').trim() }
        ext.prefix = { "${meta.id}_${meta.method_differential}_voom" }
    }

    withName: 'LIMMA_NORM' {
        ext.prefix = { "${meta.id}_${meta.method_differential}_voom_norm" }
    }

    withName: "PROPR_PROPD"{
        ext.args = { "--round_digits 5 --save_adjacency true --features_id_col gene_name"}
    }

    withName: 'GPROFILER2_GOST' {
        ext.args = [
            "--significant true",
            "--measure_underrepresentation false",
            "--correction_method gSCS",
            "--evcodes false",
            "--pval_threshold 0.05",
            "--domain_scope annotated",
            "--min_diff 1",
            "--round_digits 4",
            "--palette_name Blues",
            "--de_id_column gene_id",
            "--organism mmusculus"
        ].join(' ').trim()
    }

    withName: 'CUSTOM_TABULARTOGSEACLS' {
        ext.args = { [ "variable": "$meta.variable" ] }
    }

    withName: 'GSEA_GSEA' {
        ext.args = { "-rnd_seed 10" }
        ext.prefix = { "${meta.id}.${gene_sets.baseName}." }
    }

    withName: "PROPR_GREA"{
        ext.args = { "--permutation 10 --set_min 10 --seed 123 --round_digits 5"}
    }

    withName: 'DECOUPLER_DECOUPLER' {
        ext.prefix = { "${meta.method_differential}_${meta.id}" }
        ext.args = "--min_n 2 --transpose TRUE --ensembl_ids TRUE --methods mlm"
    }
}

params {
    decoupler_network = "https://github.com/nf-core/test-datasets/raw/differentialabundance/modules_testdata/progeny/mouse_network.tsv"
    method_differential = 'deseq2'
}

process {
    withName: 'DECOUPLER_DECOUPLER' {
       ext.prefix = {
            def method = meta.params.differential_method ?: meta.differential_method ?: "unknown"
            def prefix = "${method}_${meta.id}"
            return prefix
            }
        ext.args = {
            def features_id = meta.params?.features_id_col ?: 'gene_id'
            def features_symbol = meta.params?.features_name_col ?: 'gene_name'
            def min_n = meta.params?.decoupler_min_n ?: 5
            def methods = meta.params?.decoupler_methods ?: 'mlm'

            "--min_n ${min_n} --transpose TRUE --ensembl_ids TRUE --methods ${methods} --features_id_col ${features_id} --features_symbol_col ${features_symbol}"
        }
    }
}

process {
    withName: 'DESEQ2_DIFFERENTIAL' {
        ext.args = { [
            "--round_digits 5",
            "--vs_method rlog",
            (meta.blocking == null) ? "" : "--blocking_variables $meta.blocking"
        ].join(' ').trim() }
        ext.prefix = { "${meta.id}_${meta.method_differential}" }
    }

    withName: 'DESEQ2_NORM' {
        ext.prefix = { "${meta.id}_${meta.method_differential}_norm" }
    }

    withName: 'GPROFILER2_GOST' {
        ext.args = [
            "--significant true",
            "--measure_underrepresentation false",
            "--correction_method gSCS",
            "--evcodes false",
            "--pval_threshold 0.05",
            "--domain_scope annotated",
            "--min_diff 1",
            "--round_digits 4",
            "--palette_name Blues",
            "--de_id_column gene_id",
            "--organism mmusculus"
        ].join(' ').trim()
    }
}

process {
    withName: 'DESEQ2_DIFFERENTIAL' {
        ext.args = { [
            "--round_digits 5",
            "--vs_method rlog",
            (meta.blocking == null) ? "" : "--blocking_variables $meta.blocking"
        ].join(' ').trim() }
        ext.prefix = { "${meta.id}_${meta.method_differential}" }
    }

    withName: 'DESEQ2_NORM' {
        ext.prefix = { "${meta.id}_${meta.method_differential}_norm" }
    }

    withName: 'CUSTOM_TABULARTOGSEACLS' {
        ext.args = { [ "variable": "$meta.variable" ] }
    }

    withName: 'GSEA_GSEA' {
        ext.args = { "-rnd_seed 10" }
        ext.prefix = { "${meta.id}.${gene_sets.baseName}." }
    }
}

nextflow_workflow {

    name "Test Subworkflow DIFFERENTIAL_FUNCTIONAL_ENRICHMENT"
    script "../main.nf"
    workflow "DIFFERENTIAL_FUNCTIONAL_ENRICHMENT"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/differential_functional_enrichment"
    tag "gprofiler2"
    tag "gprofiler2/gost"
    tag "gsea"
    tag "gsea/gsea"
    tag "propr"
    tag "propr/grea"
    tag "custom"
    tag "custom/tabulartogseagct"
    tag "custom/tabulartogseacls"
    tag "custom/tabulartogseachip"
    tag "subworkflows/abundance_differential_filter"
    tag "abundance_differential_filter"
    tag "decoupler_basic"
    tag "decoupler/decoupler"

    test("test gprofiler2 - mouse") {
        tag 'gprofiler2_basic'
        config './gprofiler2.config'
        // NOTE that this generates the same outputs as the module GPROFILER2_GOST test

        when {
            workflow {
                """
                ch_input = channel.of([
                    ['id':'Condition_genotype_WT_KO', 'variable':'Condition genotype', 'reference':'WT', 'target':'KO', 'blocking':'batch'],
                    file("https://github.com/nf-core/test-datasets/raw/refs/heads/differentialabundance/modules_testdata/Condition_genotype_WT_KO.deseq2.results_filtered.tsv", checkIfExists: true),
                    [],
                    file("https://github.com/nf-core/test-datasets/raw/refs/heads/differentialabundance/modules_testdata/study.filtered.tsv", checkIfExists: true),
                    'gprofiler2'
                ])

                input[0] = ch_input
                input[1] = channel.of([[], [], [], [], [], []])
                input[2] = channel.of([
                    ['id':'Condition_genotype_WT_KO', 'variable':'Condition genotype', 'reference':'WT', 'target':'KO', 'blocking':'batch'],
                    []
                ])
                input[3] = channel.of([
                    ['id':'Condition_genotype_WT_KO', 'variable':'Condition genotype', 'reference':'WT', 'target':'KO', 'blocking':'batch'],
                    [],  //
                    '',  //
                    ''   //
                ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    workflow.out.gprofiler2_all_enrich,
                    workflow.out.gprofiler2_sub_enrich,
                    workflow.out.gprofiler2_plot_html.collect{ meta, html -> file(html).name } //assert unstable file,
                ).match()}
            )
        }
    }

    test("deseq2 + gprofiler2 - mouse") {
        tag "deseq2+gprofiler2"
        config "./deseq2_gprofiler2.config"

        setup {
            run("ABUNDANCE_DIFFERENTIAL_FILTER") {
                script "../../abundance_differential_filter/main.nf"
                workflow {
                """
                // Define test data
                def testData = [
                    expression_test_data_dir: params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/',
                    contrasts_file: 'SRP254919.contrasts.csv',
                    abundance_file: 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv',
                    samplesheet_file: 'SRP254919.samplesheet.csv'
                ]

                // Define inputs
                ch_samplesheet = channel.of([
                    [ id:'test' ],
                    file(testData.expression_test_data_dir + testData.samplesheet_file)
                ])
                ch_transcript_lengths = channel.of([ [], [] ])
                ch_control_features = channel.of([ [], [] ])
                ch_contrasts = Channel.fromPath(file(testData.expression_test_data_dir + testData.contrasts_file))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple([ id:'test' ], it, it.variable, it.reference, it.target, it.formula, it.comparison)
                    }
                    .groupTuple()
                ch_input = channel.of([
                    [ id:'test' ],
                    file(testData.expression_test_data_dir + testData.abundance_file),
                    'deseq2',  // analysis method
                    1.5,       // FC threshold
                    0.05       // padj threshold
                ])

                input[0] = ch_input
                input[1] = ch_samplesheet
                input[2] = ch_transcript_lengths
                input[3] = ch_control_features
                input[4] = ch_contrasts
                """
                }
            }
        }

        when {
            workflow {
                """
                ch_input = ABUNDANCE_DIFFERENTIAL_FILTER.out.results_genewise_filtered
                    .map { meta, results ->
                        [meta, results, [], [], 'gprofiler2']
                    }

                ch_featuresheet = ch_input
                    .map { meta, file, genesets, background, method ->
                        [meta, [], '', '']
                    }
                ch_samplesheet = ch_input
                    .map { meta, file, genesets, background, method ->
                        [meta, []]
                    }

                ch_samplesheet = ch_input
                    .map { meta, file, genesets, background, method ->
                        [meta, []]
                    }

                input[0] = ch_input
                input[1] = channel.of([[], [], [], [], [], []])
                input[2] = ch_samplesheet
                input[3] = ch_featuresheet
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    workflow.out.gprofiler2_all_enrich,
                    workflow.out.gprofiler2_sub_enrich,
                    workflow.out.gprofiler2_plot_html.collect{ meta, html -> file(html).name } //assert unstable file
                ).match()},
            )
        }
    }

    test("deseq2 + gsea - mouse") {
        tag "deseq2+gsea"
        config "./deseq2_gsea.config"

        setup {
            run("ABUNDANCE_DIFFERENTIAL_FILTER") {
                script "../../abundance_differential_filter/main.nf"
                workflow {
                """
                // Define test data
                def testDataSetup = [
                    expression_test_data_dir: params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/',
                    contrasts_file: 'SRP254919.contrasts.csv',
                    abundance_file: 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv',
                    samplesheet_file: 'SRP254919.samplesheet.csv'
                ]

                // Define inputs
                ch_samplesheet = channel.of([
                    [ id:'test' ],
                    file(testDataSetup.expression_test_data_dir + testDataSetup.samplesheet_file)
                ])
                ch_transcript_lengths = channel.of([ [ id:'test' ], [] ])
                ch_control_features = channel.of([ [ id:'test' ], [] ])
                ch_contrasts = channel.fromPath(file(testDataSetup.expression_test_data_dir + testDataSetup.contrasts_file))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple([ id:'test' ], it, it.variable, it.reference, it.target, it.formula, it.comparison)
                    }
                    .groupTuple()
                ch_input = channel.of([
                    [ id:'test' ],
                    file(testDataSetup.expression_test_data_dir + testDataSetup.abundance_file),
                    'deseq2',  // analysis method
                    1.5,       // FC threshold
                    0.05       // padj threshold
                ])

                input[0] = ch_input
                input[1] = ch_samplesheet
                input[2] = ch_transcript_lengths
                input[3] = ch_control_features
                input[4] = ch_contrasts
                """
                }
            }
        }

        when {
            workflow {
                """
                // Define test data
                def test_data_dir = params.modules_testdata_base_path + 'genomics/mus_musculus/'
                def testData = [
                    contrasts_file: test_data_dir + 'rnaseq_expression/SRP254919.contrasts.csv',
                    abundance_file: test_data_dir + 'rnaseq_expression/SRP254919.salmon.merged.gene_counts.top1000cov.tsv',
                    samplesheet_file: test_data_dir + 'rnaseq_expression/SRP254919.samplesheet.csv',
                    genesets_file: test_data_dir + 'gene_set_analysis/mh.all.v2022.1.Mm.symbols.gmt'
                ]

                // get input from upstream subworkflow
                ch_input = ABUNDANCE_DIFFERENTIAL_FILTER.out.normalised_matrix
                    .combine(channel.fromPath(testData.genesets_file))
                    .map { meta, matrix, genesets ->
                        [meta, matrix, genesets, [], 'gsea']
                    }

                // define other input files using ch_input meta
                ch_contrasts = ch_input
                    .map { meta, file, genesets, background, method -> [meta] }
                    .combine(
                        channel.fromPath(file(testData.contrasts_file))
                            .splitCsv ( header:true, sep:',' )
                            .map{
                                tuple(it, it.variable, it.reference, it.target, it.formula, it.comparison)
                            }
                    )
                    .groupTuple()
                ch_samplesheet = ch_input
                    .map { meta, file, genesets, background, method -> [meta] }
                    .combine( channel.of(file(testData.samplesheet_file)) )
                ch_featuresheet = ch_input
                    .map { meta, file, genesets, background, method -> [meta] }
                    .combine(
                        channel.of([
                            file(testData.abundance_file),
                            'gene_id',
                            'gene_name'
                        ])
                    )

                input[0] = ch_input
                input[1] = ch_contrasts
                input[2] = ch_samplesheet
                input[3] = ch_featuresheet
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    workflow.out.gsea_report_tsv
                ).match()}
            )
        }
    }

    test("propd + grea - mouse") {
        tag "propd+grea"
        config "./propd_grea.config"

        setup {
            run("ABUNDANCE_DIFFERENTIAL_FILTER") {
                script "../../abundance_differential_filter/main.nf"
                workflow {
                """
                // Define test data
                def testDataSetup = [
                    expression_test_data_dir: params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/',
                    contrasts_file: 'SRP254919.contrasts.csv',
                    abundance_file: 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv',
                    samplesheet_file: 'SRP254919.samplesheet.csv'
                ]

                // Define inputs
                ch_samplesheet = channel.of([
                    [ id:'test' ],
                    file(testDataSetup.expression_test_data_dir + testDataSetup.samplesheet_file)
                ])
                ch_transcript_lengths = channel.of([ [ id:'test' ], [] ])
                ch_control_features = channel.of([ [ id:'test' ], [] ])
                ch_contrasts = channel.fromPath(file(testDataSetup.expression_test_data_dir + testDataSetup.contrasts_file))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple([ id:'test' ], it, it.variable, it.reference, it.target, it.formula, it.comparison)
                    }
                    .groupTuple()
                ch_input = channel.of([
                    [ id:'test' ],
                    file(testDataSetup.expression_test_data_dir + testDataSetup.abundance_file),
                    'propd',   // analysis method
                    1.5,       // FC threshold
                    0.05        // significance threshold (automatically given by propd, not necessary)
                ])

                input[0] = ch_input
                input[1] = ch_samplesheet
                input[2] = ch_transcript_lengths
                input[3] = ch_control_features
                input[4] = ch_contrasts
                """
                }
            }
        }

        when {
